mapper.select:
SELECT NVL(F.FUNDACCT, ' ') AS FUNDACCT, C.CUSTNO, U.CUSTNAME AS INVNM, U.IDTYPE AS IDTP, U.IDNO, U.MOBILE, P.PMNM AS CUSTST, C.OPENDT FROM CUSTINFO C, FUNDACCOINFO F, USER_BASEINFO U, USER_ACCORLA A, (SELECT PMKY, PMCO, PMNM FROM PARAMETER WHERE PMKY = 'CUSTST' AND PMCO <> '****') P WHERE 1 = 1 AND C.CUSTST = P.PMCO AND C.CUSTNO = F.CUSTNO(+) AND (U.CMFUSERID = A.CMFUSERID AND A.ECCUSTNO = C.CUSTNO)
AND U.CUSTNAME= #{sp.custname}
AND U.IDTYPE='0' AND U.IDNO = #{sp.idno}
AND U.MOBILE= #{sp.mobile}
AND C.CUSTST= #{sp.custst}
AND C.OPENDT= #{sp.opendt}
AND F.FUNDACCT = #{sp.fundacct}
ORDER BY C.OPENDT DESC

SELECT T.TRADEACCO, B.BANKLONGNAME, T.BANKACCO, B.MOBILE, DECODE(TA.TRADEFLAG, 'Y', '正常', 'N', '无效') AS FDACST, T.OPENDT FROM TRADEACCOINFO T, THIRD_BANK_RELA C, BANKACCOINFO B, CUSTINFO C, TRADEACCORELA TA, USER_BASEINFO U, USER_ACCORLA A WHERE T.CUSTNO = B.CUSTNO AND T.TRADEACCOST = 'N' AND T.BANKNO = C.THIRDCHANNEL AND B.REALBANKNO = C.BANKNO AND T.TRADEACCO = B.TRADEACCO AND T.CUSTNO = C.CUSTNO AND (U.CMFUSERID = A.CMFUSERID AND A.ECCUSTNO = C.CUSTNO) AND T.TRADEACCO = TA.TRADEACCO
AND T.CUSTNO = #{sp.custno}
ORDER BY T.OPENDT DESC
